 @override Widget build(BuildContext context){ final d=widget.deck; final q=query.trim().toLowerCase(); final cards=d.cards.where((c)=>q.isEmpty||'${c.front} ${c.back} ${c.tags}'.toLowerCase().contains(q)).toList(); return Scaffold(appBar:AppBar(title:Text(d.name,style:const TextStyle(fontWeight:FontWeight.w800)),actions:[IconButton(onPressed:_renameDeck,icon:const Icon(Icons.edit_outlined),tooltip:s('rename')),IconButton(onPressed:_manageBoxes,icon:const Icon(Icons.layers_outlined),tooltip:s('boxes')),IconButton(onPressed:_deleteDeck,icon:const Icon(Icons.delete_outline),tooltip:s('delete'))]),floatingActionButton:FloatingActionButton.extended(onPressed:()=>_editCard(),icon:const Icon(Icons.add_rounded),label:Text(s('new_card'))),body:ListView(padding:const EdgeInsets.fromLTRB(16,10,16,110),children:[Row(children:[Expanded(child:TextField(onChanged:(v)=>setState(()=>query=v),decoration:InputDecoration(prefixIcon:const Icon(Icons.search),hintText:s('search')))),const SizedBox(width:10),FilledButton.tonalIcon(onPressed:_study,icon:const Icon(Icons.play_arrow_rounded),label:Text(s('study')))]),const SizedBox(height:14),SizedBox(height:112,child:d.boxes.isEmpty?Center(child:Text(s('no_cards'))):ListView.separated(scrollDirection:Axis.horizontal,itemCount:d.boxes.length,separatorBuilder:(_,__)=>const SizedBox(width:10),itemBuilder:(_,i){final b=d.boxes[i];final n=d.cards.where((c)=>c.boxIndex==i).length;return SizedBox(width:126,child:AnimatedGlassCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,mainAxisSize:MainAxisSize.min,children:[Icon(Icons.inventory_2_outlined,color:boxColor(b)),const Spacer(),Text(b.name,maxLines:1,overflow:TextOverflow.ellipsis,style:const TextStyle(fontWeight:FontWeight.w800)),Text('$n ${s('cards_count')}')]))); })),const SizedBox(height:16),Text('${cards.length} ${s('cards')}',style:const TextStyle(fontSize:19,fontWeight:FontWeight.w900)),const SizedBox(height:8),if(cards.isEmpty)AnimatedGlassCard(child:Padding(padding:const EdgeInsets.all(18),child:Text(s('no_cards'),textAlign:TextAlign.center))),for(final card in cards)_cardTile(card)])); }
 Widget _cardTile(FlashCard c){final d=widget.deck;final maxBox=math.max(0,d.boxes.length-1);final bi=d.boxes.isEmpty?0:c.boxIndex.clamp(0,maxBox).toInt();final b=d.boxes.isEmpty?null:d.boxes[bi];return Padding(padding:const EdgeInsets.only(bottom:10),child:AnimatedGlassCard(onTap:()=>_editCard(c),child:Row(children:[Container(width:42,height:42,color:b==null?Theme.of(context).colorScheme.primary:boxColor(b),alignment:Alignment.center,child:Text('${bi+1}',style:const TextStyle(color:Colors.white,fontWeight:FontWeight.w700))),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,mainAxisSize:MainAxisSize.min,children:[Text(c.front.isEmpty?'🖼️':c.front,maxLines:1,overflow:TextOverflow.ellipsis,style:const TextStyle(fontWeight:FontWeight.w800)),const SizedBox(height:4),Text(c.back.isEmpty?'🖼️':c.back,maxLines:2,overflow:TextOverflow.ellipsis),if(c.tags.trim().isNotEmpty)Text(c.tags,style:TextStyle(fontSize:12,color:Theme.of(context).colorScheme.onSurfaceVariant))])),IconButton(onPressed:(){setState(()=>c.favorite=!c.favorite);widget.onChanged();},icon:Icon(c.favorite?Icons.star:Icons.star_border,color:c.favorite?Colors.amber:null))]))); }
 Future<void> _renameDeck()async{final c=TextEditingController(text:widget.deck.name);final name=await showDialog<String>(context:context,builder:(_)=>AlertDialog(title:Text(s('rename')),content:TextField(controller:c,autofocus:true),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:Text(s('cancel'))),FilledButton(onPressed:()=>Navigator.pop(context,c.text.trim()),child:Text(s('save')))]));c.dispose();if(name!=null&&name.isNotEmpty){widget.deck.name=name;setState((){});widget.onChanged();}}
