 Future<void> _study()async{final now=DateTime.now();final due=widget.deck.cards.where((c)=>!c.dueAt.isAfter(now)).toList();final choice=await showModalBottomSheet<String>(context:context,showDragHandle:true,builder:(_)=>SafeArea(child:Column(mainAxisSize:MainAxisSize.min,children:[ListTile(title:Text(s('study_type'),style:const TextStyle(fontWeight:FontWeight.w800))),ListTile(leading:const Icon(Icons.bolt_outlined),title:Text(s('cards_ready')),subtitle:Text('${due.length} ${s('cards_count')}'),onTap:()=>Navigator.pop(context,'due')),ListTile(leading:const Icon(Icons.all_inclusive),title:Text(s('all')),onTap:()=>Navigator.pop(context,'all')),ListTile(leading:const Icon(Icons.star_outline),title:Text(s('favorite_only')),onTap:()=>Navigator.pop(context,'favorites'))])));if(!mounted||choice==null)return;final selected=choice=='all'?[...widget.deck.cards]:choice=='favorites'?widget.deck.cards.where((c)=>c.favorite).toList():due;if(selected.isEmpty){ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s('no_review'))));return;}await Navigator.push(context,MaterialPageRoute(builder:(_)=>StudyPage(deck:widget.deck,settings:widget.settings,studyCards:selected,onChanged:widget.onChanged)));if(mounted)setState((){});}
