class _BoxManager extends StatefulWidget{final Deck deck;final VoidCallback onChanged;const _BoxManager({required this.deck,required this.onChanged});@override State<_BoxManager> createState()=>_BoxManagerState();}
class _BoxManagerState extends State<_BoxManager>{String s(String k)=>AppStrings.t(context,k);Future<void>_add()async{final c=TextEditingController(text:'${s('box')} ${widget.deck.boxes.length+1}');final name=await showDialog<String>(context:context,builder:(_)=>AlertDialog(title:Text(s('add_box')),content:TextField(controller:c,autofocus:true,decoration:InputDecoration(labelText:s('box_name'))),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:Text(s('cancel'))),FilledButton(onPressed:()=>Navigator.pop(context,c.text.trim()),child:Text(s('save')))]));c.dispose();if(name==null||name.isEmpty)return;widget.deck.boxes.add(LeitnerBox(id:uid(),name:name,colorValue:Colors.primaries[widget.deck.boxes.length%Colors.primaries.length].toARGB32()));setState((){});widget.onChanged();}Future<void>_rename(int i)async{final c=TextEditingController(text:widget.deck.boxes[i].name);final name=await showDialog<String>(context:context,builder:(_)=>AlertDialog(title:Text(s('rename')),content:TextField(controller:c),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:Text(s('cancel'))),FilledButton(onPressed:()=>Navigator.pop(context,c.text.trim()),child:Text(s('save')))]));c.dispose();if(name==null||name.isEmpty)return;widget.deck.boxes[i].name=name;setState((){});widget.onChanged();}Future<void>_delete(int i)async{if(widget.deck.boxes.length<=1)return;final ok=await showDialog<bool>(context:context,builder:(_)=>AlertDialog(title:Text(s('delete_box')),content:Text(s('delete_box_confirm')),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:Text(s('cancel'))),FilledButton(onPressed:()=>Navigator.pop(context,true),child:Text(s('delete')))]));if(ok!=true)return;widget.deck.boxes.removeAt(i);for(final c in widget.deck.cards){if(c.boxIndex==i)c.boxIndex=0;else if(c.boxIndex>i)c.boxIndex--;}setState((){});widget.onChanged();}@override Widget build(BuildContext context)=>SafeArea(child:SizedBox(height:math.min(560,MediaQuery.sizeOf(context).height*.75),child:Column(children:[Padding(padding:const EdgeInsets.fromLTRB(16,4,8,4),child:Row(children:[Expanded(child:Text(s('boxes'),style:const TextStyle(fontSize:20,fontWeight:FontWeight.w800))),IconButton(onPressed:_add,icon:const Icon(Icons.add))])),const Divider(height:1),Expanded(child:ListView.builder(itemCount:widget.deck.boxes.length,itemBuilder:(_,i){final b=widget.deck.boxes[i];final n=widget.deck.cards.where((c)=>c.boxIndex==i).length;return ListTile(leading:Container(width:40,height:40,color:boxColor(b),alignment:Alignment.center,child:Text('${i+1}',style:const TextStyle(color:Colors.white,fontWeight:FontWeight.w700))),title:Text(b.name),subtitle:Text('$n ${s('cards_count')}'),trailing:Wrap(children:[IconButton(onPressed:()=>_rename(i),icon:const Icon(Icons.edit_outlined)),IconButton(onPressed:()=>_delete(i),icon:const Icon(Icons.delete_outline))]));}))])));}
